components.css:
.thread { border: 1px solid var(--line); border-radius: var(--radius-lg); padding: 16px; max-width: 560px; }
.meta { font-size: 12px; color: var(--muted); }
.body { margin: 6px 0 12px; font-size: 16px; }
.row { display: flex; gap: 8px; }
input { flex: 1; font: inherit; font-size: 14px; padding: 8px 12px; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); color: var(--fg); }
button { font: inherit; font-size: 14px; padding: 8px 14px; border: 0; border-radius: var(--radius-md); background: var(--fg); color: var(--bg); }
.alert { margin: 10px 0 0; font-size: 13.5px; color: var(--warn); }
.decided { margin: 0; font-size: 14px; color: var(--ok); }
